arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H 'Content-Type: application/json' -d '{"token":"***","exclude_archived":false,"types":"public_channel,private_channel","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for c in d.get('channels',[]):
    topic=c.get('topic') or ''
    if isinstance(topic,dict): topic=topic.get('value','')
    if 'checkout' in (c.get('name','')+topic).lower():
        print(c.get('id'),c.get('name'),'archived' if c.get('is_archived') else 'active','| topic:',topic)
print('---all archived---')
for c in d.get('channels',[]):
    if c.get('is_archived'):
        print(c.get('id'),c.get('name'),'| topic:',(c.get('topic') or {}))
"

